<script setup lang="ts">
import { CheckCheck,RefreshCw } from '@lucide/vue'
import { SALON_TIMEZONE } from '~~/shared/constants/business'
definePageMeta({layout:'admin',middleware:'admin'})
type Message={id:string;name:string;phone:string|null;email:string|null;message:string;status:'new'|'read'|'replied'|'archived';createdAt:string}
const rows=ref<Message[]>([]),loading=ref(false),error=ref(''),success=ref(''),search=ref(''),status=ref('')
async function load(){loading.value=true;error.value='';try{const result=await $fetch<{items:Message[]}>('/api/admin/manage',{query:{resource:'contacts'}});rows.value=result.items.filter((item)=>!search.value||`${item.name} ${item.phone||''} ${item.email||''} ${item.message}`.toLocaleLowerCase('fr').includes(search.value.toLocaleLowerCase('fr'))).filter((item)=>!status.value||item.status===status.value)}catch(err){error.value=(err as{data?:{statusMessage?:string}})?.data?.statusMessage||'Les messages ne peuvent pas être chargés.'}finally{loading.value=false}}
watch([search,status],load,{immediate:true})
function localDate(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
async function update(row:Message,next:Message['status']){try{await $fetch(`/api/admin/manage/${row.id}`,{method:'PATCH',body:{resource:'contacts',data:{status:next}}});success.value='Statut enregistré.';await load()}catch(err){error.value=(err as{data?:{statusMessage?:string}})?.data?.statusMessage||'Le statut n’a pas été modifié.'}}
useSeoMeta({title:'Messages — Administration',robots:'noindex,nofollow'})
</script>
<template><div class="messages-page"><div class="admin-page-head"><div><span class="section-kicker">Relation cliente</span><h1>Messages.</h1><p>Les messages du formulaire de contact, enregistrés par salon; aucun envoi de réponse n’est présumé.</p></div><button class="admin-inline-action" :disabled="loading" @click="load"><RefreshCw :size="13"/> Actualiser</button></div><p v-if="error" class="admin-alert" role="alert">{{error}}</p><p v-if="success" class="admin-success" role="status">{{success}}</p><div class="admin-toolbar"><input v-model="search" class="form-control" placeholder="Nom, téléphone, courriel ou message" aria-label="Rechercher les messages"><select v-model="status" class="form-control" aria-label="Filtrer par état"><option value="">Tous les états</option><option value="new">Nouveau</option><option value="read">Lu</option><option value="replied">Répondu hors du site</option><option value="archived">Archivé</option></select></div><section class="message-list"><article v-for="row in rows" :key="row.id" class="admin-card message-card"><div class="message-meta"><div><h2>{{row.name}}</h2><p>{{row.phone||'Sans téléphone'}} · {{row.email||'Sans e-mail'}}</p></div><span class="status-pill">{{row.status}}</span></div><p class="message-copy">{{row.message}}</p><div class="message-footer"><time :datetime="row.createdAt">{{localDate(row.createdAt)}}</time><div class="admin-actions"><button v-if="row.status==='new'" @click="update(row,'read')"><CheckCheck :size="12"/> Marquer lu</button><button v-if="row.status!=='replied'&&row.status!=='archived'" @click="update(row,'replied')">Noter une réponse externe</button><button v-if="row.status!=='archived'" @click="update(row,'archived')">Archiver</button></div></div></article><p v-if="!loading&&!rows.length" class="admin-card admin-empty">Aucun message enregistré.</p><p v-if="loading" class="admin-card admin-empty">Chargement…</p></section></div></template>
<style scoped>.messages-page{display:grid;gap:.8rem}.message-list{display:grid;gap:.6rem}.message-card{padding:1rem}.message-meta,.message-footer{display:flex;align-items:flex-start;justify-content:space-between;gap:.7rem}.message-meta h2{margin:0;font-family:var(--font-display);font-size:1.25rem;font-weight:500}.message-meta p,.message-footer time{margin:.2rem 0;color:#8a7d74;font-size:.62rem}.message-copy{white-space:pre-wrap;line-height:1.7;color:#4d403b;font-size:.75rem}.message-footer{align-items:center;border-top:1px solid #eee7df;padding-top:.6rem}@media(max-width:700px){.message-footer{align-items:flex-start;flex-direction:column}}</style>
